package com.seoul2033wiki

import android.util.Log
import java.net.URLEncoder

/**
 * 확장팩 인카운터 OCR 텍스트 → 나무위키 확장팩 섹션 URL 매핑
 *
 * 대상: /w/서울 2033/랜덤 인카운터/(확장팩이름)#섹션앵커
 *
 * ── 구조 ─────────────────────────────────────────────────────────────────
 * EXPANSION_MAP: Map<확장팩이름, List<Pair<키구문, 섹션앵커>>>
 *
 *   - 확장팩별로 독립된 매핑 리스트를 관리
 *   - 하나의 섹션에 키 여러 개 등록 가능 (같은 앵커에 Pair를 추가)
 *   - 새 확장팩 추가 시 EXPANSION_MAP에 항목만 추가
 *
 * ── 매칭 방식 ────────────────────────────────────────────────────────────
 *   - 1차: normalize() 적용 후 exact 포함 매칭, 가장 긴 키 우선 (키 최소 8자)
 *   - 2차: 절반 키 포함 매칭 (화면 일부만 캡처된 경우)
 *   - 3차: fuzzyScore 기반 유사도 매칭 (OCR 오인식 흡수, 임계값 0.70)
 *
 * ── 현재 커버 확장팩 ──────────────────────────────────────────────────────
 *   - 고양이를 부탁해, 구로혈액공단, 노 맨즈 랜드, 노 맨즈 랜드 2
 *   - 동물 친구들, 동물 친구들 2, 뒷골목의 제왕, 드래곤 마운틴
 *   - 맛집 기행, 무기속 위임, 물물 교환, 미. 연. 시.
 *   - 밀라노 칼리브로, 바운티 헌터, 방사능 갤러리, 발명의 날
 *   - 분노의 도로, 블랙 아웃, 사건 25시, 사실상 공무원의 이론
 *   - 서울 2015 : 예삐전, 서울 무림맹, 서울림픽, 서울의 밤
 *   - 세상에 나쁜 쥐는 없다, 신인 작가 단편선, 신인 작가 단편선 2
 *   - 아기 황소너구리, 언더 월드, 엽총과 송곳니, 옛날 옛적에
 *   - 온 에어 서울, 요리왕, 원 피스 쉽, 잠실 칼리파
 *   - 장미의 이름으로, 재건, 죄와 벌, 천공의 묵시록
 *   - 카지노 로얄, 프린세슘 메이커, 한강 러닝, 핵겨울왕국
 *   - 황소너구리 왕국
 *
 * ── 패스스루 확장팩 (섹션 탐지 없이 최상단 URL 반환) ─────────────────────
 *   - 마님의 바텐더
 */
object ExpansionEncounterResolver {

    private const val TAG = "ExpansionEncounterResolver"
    private const val BASE = "https://namu.wiki"

