            "시위가발생했습니다왕궁앞에이상한황소너구리들이나타나서행패를부리고있습니다" to "황소너구리 시위대",
            "단단구리를석방하라짜파구리를왕으로인간은우리의적이다" to "황소너구리 시위대",
            "말린뱀포섭한다말린뱀황소너구리시위대웅변lv2인간은너희와공존하고싶어해70%" to "황소너구리 시위대",

