            "사람들이제법모여사는판자촌을지나가다가누군가쩌렁쩌렁외치는소리에옆을돌아봅니다" to "진입 인카운터",
            "어어그런데어째열린문이당신쪽으로기울어지는것같은데요" to "진입 인카운터",

