            "안녕하십니까마침노동력이부족해서곤란했습니다" to "3일장",
            "요즘같은시대에기름잔뜩쓴부침개라니이것만해도엄청나게호화로운식사입니다" to "3일장",
            "사람들은빈소에남아서간간이이야기를나누고음식도조금씩먹습니다카드놀이를하기도하는군요" to "3일장",
            "절친한친구의빈소를지키기위해카드판에앉았다가웬꾼들에게호되게당하고있는모양이로군요" to "3일장",
            "이보게자네자네가저돈통좀지켜주게" to "3일장",
