            "시간을마냥끌수도없으니탐색할곳을정해야할것같은데요" to "연고 없는 시신",

            // 2.7 율이
            "이바보깡통같으니어려운일도아니잖아그냥몇마디만해주면된다니까" to "율이",
            "낯익은목소리가누군가와실랑이하는소리가들려옵니다저거데스나이트인것같죠" to "율이",
            "후속지침을내려주시기바랍니다" to "율이",

            // 2.8 묘지 정비
            "저걸언제다고치나어이장례지도사그런건못해" to "묘지 정비",

            // 2.9 마지막 의뢰
            "또다시데스나이트로부터연락이끊겼습니다저번에도이런적이있었죠" to "마지막 의뢰",
            "마침데스나이트가차려놓은사무실근처인데한번들러봅시다" to "마지막 의뢰",
            "녀석과다양한끝을배웅했습니다그런데마지막이이렇게되다뇨" to "마지막 의뢰",
            "당신은충동적으로근처에떨어진널빤지를줍습니다" to "마지막 의뢰"
        )
    )

    // ── normalize ────────────────────────────────────────────────────────
    private fun normalize(s: String) =
        s.replace(Regex("""[\s·!?.,:'ー–—\-]"""), "").lowercase()


    // ── prefix 버킷 인덱스 ────────────────────────────────────────────────
    // expansion별 키를 앞 5글자로 그룹화. resolve 시 입력 텍스트의 슬라이딩 윈도우로
    // 해당 버킷만 검사 → fuzzy 연산 대상을 ~95% 축소.
    private const val PREFIX_LEN = 5

    // Map<prefix, List<Triple(expansion, key, anchor)>>
    private val prefixIndex: Map<String, List<Triple<String, String, String>>> by lazy {
        val map = HashMap<String, MutableList<Triple<String, String, String>>>()
        for ((expansion, entries) in EXPANSION_MAP) {
            for ((key, anchor) in entries) {
                if (key.length >= PREFIX_LEN) {
                    val p = key.substring(0, PREFIX_LEN)
                    map.getOrPut(p) { mutableListOf() }.add(Triple(expansion, key, anchor))
                }
            }
        }
        map
    }

    // 후반부 prefix 인덱스 (절반 포함 매칭용)
    private val suffixIndex: Map<String, List<Triple<String, String, String>>> by lazy {
        val map = HashMap<String, MutableList<Triple<String, String, String>>>()
        for ((expansion, entries) in EXPANSION_MAP) {
            for ((key, anchor) in entries) {
                if (key.length >= 12) {
                    val secondHalf = key.substring(key.length / 2)
                    if (secondHalf.length >= PREFIX_LEN) {
                        val p = secondHalf.substring(0, PREFIX_LEN)
                        map.getOrPut(p) { mutableListOf() }.add(Triple(expansion, key, anchor))
                    }
                }
            }
        }
        map
    }

    /**
     * 섹션 탐지 없이 확장팩 최상단 페이지로만 연결하는 패스스루 확장팩 목록.
     * 이 목록에 있는 확장팩은 본문 OCR을 시도하지 않고 바로 반환.
     */
    private val PASSTHROUGH_EXPANSIONS: Set<String> = setOf(
        "마님의 바텐더"
    )

    /**
     * 이름이 비슷한 확장팩들을 하나로 묶는 그룹 맵.
     * 예) "동물 친구들 2" 인식 → "동물 친구들", "동물 친구들 2" 양쪽 모두 탐색.
     *
     * key   : normalize() 적용 후 확장팩 이름
     * value : 함께 탐색할 확장팩 이름 목록 (자기 자신 포함)
     */
    private val EXPANSION_GROUP_MAP: Map<String, List<String>> = buildExpansionGroups()

    private fun buildExpansionGroups(): Map<String, List<String>> {
        // EXPANSION_MAP 키 중에서 숫자(2, 3 …)로 끝나는 확장팩을 기준으로
        // 같은 기본 이름을 공유하는 것들끼리 묶는다.
        // 예) "동물 친구들" / "동물 친구들 2"  → 기본 이름 "동물 친구들"
        //     "노 맨즈 랜드" / "노 맨즈 랜드 2" → 기본 이름 "노 맨즈 랜드"
        val allKeys = EXPANSION_MAP.keys.toList()
        val result = mutableMapOf<String, MutableList<String>>()

        for (key in allKeys) {
            // 끝에 숫자(공백 포함)가 붙은 형태인지 확인
            val baseNameFull = key.replace(Regex("""\s*\d+\s*$"""), "").trim()
            val baseName = normalize(baseNameFull)

            // 이 key 자신을 그룹에 추가
            result.getOrPut(normalize(key)) { mutableListOf() }.add(key)

            // 같은 baseName을 가진 다른 확장팩들을 찾아서 서로의 그룹에 추가
            if (baseName != normalize(key)) {
                result.getOrPut(baseName) { mutableListOf() }
                // baseName 그룹에도 이 key 추가 (중복 방지)
                val baseGroup = result.getOrPut(baseName) { mutableListOf() }
                if (!baseGroup.contains(key)) baseGroup.add(key)
            }
        }

        // 같은 baseName을 공유하는 키들끼리 그룹을 병합
        val mergedResult = mutableMapOf<String, List<String>>()
        for (key in allKeys) {
            val normKey = normalize(key)
            val baseNameFull = key.replace(Regex("""\s*\d+\s*$"""), "").trim()
            val baseName = normalize(baseNameFull)

            // 같은 기본 이름을 공유하는 모든 확장팩 수집
            val siblings = allKeys.filter { sibling ->
                val sibBase = normalize(sibling.replace(Regex("""\s*\d+\s*$"""), "").trim())
                sibBase == baseName || normalize(sibling) == baseName || sibBase == normKey
            }.distinct()

            mergedResult[normKey] = if (siblings.size > 1) siblings else listOf(key)
        }

        return mergedResult
    }

    /**
     * knownExpansion에 해당하는 확장팩 그룹 전체 목록을 반환한다.
     * 예) "동물 친구들 2" → ["동물 친구들", "동물 친구들 2"]
     *     "노 맨즈 랜드"  → ["노 맨즈 랜드", "노 맨즈 랜드 2"]
     *     "드래곤 마운틴" → ["드래곤 마운틴"]  (혼자이면 그대로)
     */
    private fun getExpansionGroup(knownExpansion: String): List<String> {
        val normExp = normalize(knownExpansion)
        val group = EXPANSION_GROUP_MAP[normExp]
        if (!group.isNullOrEmpty()) return group

        // 그룹 맵에 없으면 EXPANSION_MAP에서 직접 탐색 (사용자 등록 확장팩 등)
        val directMatch = EXPANSION_MAP.keys.filter { normalize(it) == normExp }
        return directMatch.ifEmpty { listOf(knownExpansion) }
    }


    // ── 힌트 맵 ──────────────────────────────────────────────────────────────
    // 확장팩별로 분리 관리. EncounterHints.kt 참조.
    fun hint(expansion: String, anchor: String): String? = EncounterHints.getExpansion(expansion, anchor)

    fun resolve(rawText: String, knownExpansion: String? = null, ctx: android.content.Context? = null): ResolvedEntry? {
        // 패스스루 확장팩: 섹션 탐지 없이 확장팩 최상단 URL 반환
        // 1) 하드코딩 패스스루 목록
        if (knownExpansion != null && normalize(knownExpansion) in PASSTHROUGH_EXPANSIONS.map { normalize(it) }) {
            Log.d(TAG, "패스스루 확장팩 (하드코딩): '$knownExpansion'")
            return ResolvedEntry(
                title = knownExpansion, pageNum = "",
                type = EntryType.EXPANSION_ENCOUNTER,
                url = buildExpansionUrl(knownExpansion, "")
            )
        }
        // 2) 사용자 등록 확장팩 → 섹션 키가 없으므로 패스스루 처리
        if (knownExpansion != null && ctx != null) {
            val customExpansions = CustomItemManager.getExpansions(ctx)
            if (normalize(knownExpansion) in customExpansions.map { normalize(it) }) {
                Log.d(TAG, "패스스루 확장팩 (사용자 등록): '$knownExpansion'")
                return ResolvedEntry(
                    title = knownExpansion, pageNum = "",
                    type = EntryType.EXPANSION_ENCOUNTER,
                    url = buildExpansionUrl(knownExpansion, "")
                )
            }
        }

        // ── 텍스트 분할 전략 ──────────────────────────────────────────────
        // beforePage가 길어질수록 현재 화면 텍스트는 뒷부분에 있음.
        // 1) 뒤 1000자: 확장팩/이야기 태그 + 현재 인카운터 본문 탐지 (우선)
        // 2) 앞 1000자: 앞부분에 키가 등장하는 인카운터 커버 (fallback)
        val rawNorm = normalize(rawText)
        val backInput  = if (rawNorm.length > 1000) rawNorm.takeLast(1000) else rawNorm
        val frontInput = if (rawNorm.length > 1000) rawNorm.take(1000) else rawNorm

        // knownExpansion이 있으면 해당 그룹 이름만 필터 Set으로 만들어 인덱스 결과를 걸러냄
        val groupNames: Set<String>? = if (knownExpansion != null) {
            getExpansionGroup(knownExpansion).map { normalize(it) }.toSet()
        } else null

        // ── 1차: prefix 인덱스로 후보 추출 후 완전 포함 매칭 ────────────
        // 뒤 1000자 우선, 없으면 앞 1000자에서 재시도
        fun exactMatch(input: String): Triple<String, String, String> {
            val seen = HashSet<String>()
            var bestKey = ""; var bestAnchor = ""; var bestExpansion = ""
            for (start in 0..input.length - PREFIX_LEN) {
                val prefix = input.substring(start, start + PREFIX_LEN)
                val bucket = prefixIndex[prefix] ?: continue
                for ((expansion, key, anchor) in bucket) {
                    if (groupNames != null && normalize(expansion) !in groupNames) continue
                    val id = "$expansion::$key"
                    if (!seen.add(id)) continue
                    if (key.length >= 8 && input.contains(key) && key.length >= bestKey.length) {
                        bestKey = key; bestAnchor = anchor; bestExpansion = expansion
                    }
                }
            }
            return Triple(bestKey, bestAnchor, bestExpansion)
        }

        var (bestKey, bestAnchor, bestExpansion) = exactMatch(backInput)
        if (bestKey.isEmpty() && frontInput !== backInput)
            exactMatch(frontInput).also { (k, a, e) -> if (k.isNotEmpty()) { bestKey = k; bestAnchor = a; bestExpansion = e } }

        if (bestKey.isNotEmpty()) {
            Log.d(TAG, "확장팩 완전포함 매칭: '$bestExpansion' > '$bestAnchor' (키=${bestKey.take(15)}...)")
            return ResolvedEntry(
                title = "$bestExpansion - $bestAnchor", pageNum = "",
                type = EntryType.EXPANSION_ENCOUNTER,
                url = buildExpansionUrl(bestExpansion, bestAnchor)
            )
        }

        // ── 2차: suffix 인덱스로 절반 포함 매칭 ─────────────────────────
        fun halfMatch(input: String): Triple<String, String, String> {
            val halfSeen = HashSet<String>()
            var hBestKey = ""; var hBestAnchor = ""; var hBestExpansion = ""
            for (start in 0..input.length - PREFIX_LEN) {
                val prefix = input.substring(start, start + PREFIX_LEN)
                val fBucket = prefixIndex[prefix] ?: emptyList()
                for ((expansion, key, anchor) in fBucket) {
                    if (groupNames != null && normalize(expansion) !in groupNames) continue
                    if (key.length < 12) continue
                    val id = "f::$expansion::$key"
                    if (!halfSeen.add(id)) continue
                    val firstHalf = key.substring(0, key.length / 2)
                    if (firstHalf.length >= 6 && input.contains(firstHalf) && key.length >= hBestKey.length) {
                        hBestKey = key; hBestAnchor = anchor; hBestExpansion = expansion
                    }
                }
                val sBucket = suffixIndex[prefix] ?: emptyList()
                for ((expansion, key, anchor) in sBucket) {
                    if (groupNames != null && normalize(expansion) !in groupNames) continue
                    val id = "s::$expansion::$key"
                    if (!halfSeen.add(id)) continue
                    val secondHalf = key.substring(key.length / 2)
                    if (secondHalf.length >= 6 && input.contains(secondHalf) && key.length >= hBestKey.length) {
                        hBestKey = key; hBestAnchor = anchor; hBestExpansion = expansion
                    }
                }
            }
            return Triple(hBestKey, hBestAnchor, hBestExpansion)
        }

        var (hBestKey, hBestAnchor, hBestExpansion) = halfMatch(backInput)
        if (hBestKey.isEmpty() && frontInput !== backInput)
            halfMatch(frontInput).also { (k, a, e) -> if (k.isNotEmpty()) { hBestKey = k; hBestAnchor = a; hBestExpansion = e } }

        if (hBestKey.isNotEmpty()) {
            Log.d(TAG, "확장팩 절반포함 매칭: '$hBestExpansion' > '$hBestAnchor' (키=${hBestKey.take(15)}...)")
            return ResolvedEntry(
                title = "$hBestExpansion - $hBestAnchor", pageNum = "",
                type = EntryType.EXPANSION_ENCOUNTER,
                url = buildExpansionUrl(hBestExpansion, hBestAnchor)
            )
        }

        // ── 3차: 동일 후보들만 fuzzy 매칭 (전체 순회 없음) ───────────────
        data class FuzzyCandidate(val key: String, val anchor: String, val expansion: String, val score: Double)

        fun fuzzyMatch(input: String): FuzzyCandidate? {
            val fuzzySeen = HashSet<String>()
            val candidates = mutableListOf<FuzzyCandidate>()
            for (start in 0..input.length - PREFIX_LEN) {
                val prefix = input.substring(start, start + PREFIX_LEN)
                val bucket = prefixIndex[prefix] ?: continue
                for ((expansion, key, anchor) in bucket) {
                    if (groupNames != null && normalize(expansion) !in groupNames) continue
                    if (key.length < 8) continue
                    val id = "$expansion::$key"
                    if (!fuzzySeen.add(id)) continue
                    val score = fuzzyScore(input, key)
                    if (score >= FUZZY_THRESHOLD) candidates.add(FuzzyCandidate(key, anchor, expansion, score))
                }
            }
            val topScore = candidates.maxOfOrNull { it.score } ?: 0.0
            return candidates.lastOrNull { it.score == topScore }
        }

        val fuzzyCandidates = mutableListOf<FuzzyCandidate>()
        fuzzyMatch(backInput)?.let { fuzzyCandidates.add(it) }
        if (frontInput !== backInput) fuzzyMatch(frontInput)?.let { fuzzyCandidates.add(it) }
        val fuzzyTopScore = fuzzyCandidates.maxOfOrNull { it.score } ?: 0.0
        val fuzzyBest = fuzzyCandidates.lastOrNull { it.score == fuzzyTopScore }

        if (fuzzyBest != null) {
            Log.d(TAG, "확장팩 유사도 매칭: '${fuzzyBest.expansion}' > '${fuzzyBest.anchor}' (점수=${"%.2f".format(fuzzyBest.score)}, 키=${fuzzyBest.key.take(15)}...)")
            return ResolvedEntry(
                title = "${fuzzyBest.expansion} - ${fuzzyBest.anchor}", pageNum = "",
                type = EntryType.EXPANSION_ENCOUNTER,
                url = buildExpansionUrl(fuzzyBest.expansion, fuzzyBest.anchor)
            )
        }

        Log.d(TAG, "확장팩 인카운터 매칭 실패 (확장팩=${knownExpansion ?: "전체탐색"})")
        return null
    }

    // ── 유사도 함수 (MainStoryEncounterResolver와 동일 구조) ──────────────────

    private fun fuzzyScore(text: String, key: String): Double {
        // 1차: 3-gram 포함 매칭
        val keyGrams = buildNgrams(key)
        if (keyGrams.isEmpty()) return 0.0
        val matchedGrams = keyGrams.count { gram -> text.contains(gram) }
        val ngramScore = matchedGrams.toDouble() / keyGrams.size

        // 2차: 슬라이딩 윈도우 편집거리 매칭
        val slideScore = bestSlideScore(text, key)

        return maxOf(ngramScore, slideScore)
    }

    private fun buildNgrams(s: String): List<String> {
        if (s.length < N_GRAM_SIZE) return if (s.isNotEmpty()) listOf(s) else emptyList()
        return (0..s.length - N_GRAM_SIZE).map { s.substring(it, it + N_GRAM_SIZE) }
    }

    /**
     * OCR 텍스트(text)는 항상 key보다 길고 앞뒤로 잡음이 섞인다.
     * → window 크기를 key 길이 ± allowed 범위로 넓혀 슬라이딩.
     *   중간에 잡음 글자가 삽입/삭제돼도 정렬이 어긋나지 않도록 허용.
     *
     * 허용 편집거리: key 길이의 20% (OCR 오인식 + 중간 잡음 흡수)
     * 점수: 1.0 - (실제거리 / 허용거리), 허용거리 초과 시 0.0
     */
    private fun bestSlideScore(text: String, key: String): Double {
        val allowed = maxOf(1, (key.length * 0.20).toInt())
        val winMin = maxOf(1, key.length - allowed)
        val winMax = key.length + allowed
        var bestDist = allowed + 1
        for (start in 0..maxOf(0, text.length - winMin)) {
            val end = minOf(text.length, start + winMax)
            if (end - start < winMin) break
            val window = text.substring(start, end)
            val d = editDistance(window, key, allowed)
            if (d < bestDist) bestDist = d
            if (bestDist == 0) break
        }
        if (bestDist > allowed) return 0.0
        return maxOf(0.0, 1.0 - bestDist.toDouble() / allowed)
    }

    /**
     * 레벤슈타인 편집거리.
     * window와 key는 항상 같은 길이로 호출되므로 길이 차이 조기종료는 없애고
     * rowMin 기반 조기종료만 유지한다.
     */
    private fun editDistance(a: String, b: String, rowExit: Int): Int {
        if (a == b) return 0
        if (a.isEmpty()) return b.length
        if (b.isEmpty()) return a.length
        val prev = IntArray(b.length + 1) { it }
        val curr = IntArray(b.length + 1)
        for (i in 1..a.length) {
            curr[0] = i
            var rowMin = curr[0]
            for (j in 1..b.length) {
                curr[j] = if (a[i - 1] == b[j - 1]) prev[j - 1]
                else 1 + minOf(prev[j], curr[j - 1], prev[j - 1])
                if (curr[j] < rowMin) rowMin = curr[j]
            }
            if (rowMin > rowExit) return rowExit + 1
            prev.indices.forEach { prev[it] = curr[it] }
        }
        return curr[b.length]
    }

    /**
     * 확장팩 인덱스 페이지 URL (섹션 앵커 없음).
     * 본문 매칭 실패 시 폴백으로 사용.
     */
    fun buildIndexUrl(expansion: String): String {
        val basePath = URLEncoder.encode("서울 2033/랜덤 인카운터/$expansion", "UTF-8")
            .replace("+", "%20")
        return "$BASE/w/$basePath"
    }

    private fun buildExpansionUrl(expansion: String, anchor: String): String {
        val basePath = URLEncoder.encode("서울 2033/랜덤 인카운터/$expansion", "UTF-8")
            .replace("+", "%20")
        if (anchor.isEmpty()) return "$BASE/w/$basePath"
        val anchorEncoded = URLEncoder.encode(anchor, "UTF-8").replace("+", "%20")
        return "$BASE/w/$basePath#$anchorEncoded"
    }
}